// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { TargetIcon, ZapIcon } from 'lucide-react'

import {
  BrowserChrome,
  DemoStage,
  DockHeader,
  mockImage,
  type Build,
} from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import { CAPTIONS, EXPORTS, HOST, NEXT_SELECTOR, PAGE_ONE, PAGE_TWO, ROW_SELECTOR } from './script'

const ROWS = [...PAGE_ONE, ...PAGE_TWO]
const ROW_H = 16

const build: Build = ({
  tl,
  q,
  qa,
  pos,
  step,
  final,
  move,
  click,
  type,
  scramble,
  count,
  wait,
  cursorOut,
}) => {
  const phase = (text: string, at?: string) =>
    tl.to(q('phase'), { text: { value: text, delimiter: '' }, duration: 0.01 }, at)

  step(0)
  move('detect')
  click('detect')
  tl.fromTo(
    q('lasso'),
    { clipPath: 'inset(0% 100% 100% 0%)', opacity: 1 },
    { clipPath: 'inset(0% 0% 0% 0%)', duration: 0.7, ease: 'power2.inOut' },
    '<0.1',
  )
  tl.to(qa('card'), { outlineColor: 'rgba(96,165,250,0.9)', duration: 0.2, stagger: 0.06 }, '-=0.2')
  type('row-sel', ROW_SELECTOR, { at: '<', speed: 0.02 })

  step(1, '+=0.3')
  phase('extracting')
  tl.fromTo(
    qa('row').slice(0, PAGE_ONE.length),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.08, ease: 'power3.out' },
  )
  count('row-count', PAGE_ONE.length, { at: '<', duration: 0.5 })
  phase('idle', '>')

  step(2, '+=0.4')
  move('mode')
  click('mode')
  tl.to(q('mode-text'), { text: { value: 'Click next', delimiter: '' }, duration: 0.01 }, '<')
  type('next-sel', NEXT_SELECTOR, { speed: 0.03 })
  move('crawl')
  click('crawl')
  phase('waiting', '<')
  tl.to(
    q('pager-next'),
    { backgroundColor: 'rgba(96,165,250,0.35)', duration: 0.2, yoyo: true, repeat: 1 },
    '+=0.4',
  )
  phase('paginating', '<')
  tl.to(q('lasso'), { opacity: 0, duration: 0.15 }, '<')
  tl.to(qa('card'), { outlineColor: 'rgba(96,165,250,0)', duration: 0.15 }, '<')
  qa('card-name').forEach((name, index) =>
    scramble(name, PAGE_TWO[index].name, { at: index === 0 ? '<' : '<0.03', duration: 0.4 }),
  )
  qa('card-price').forEach((price, index) =>
    scramble(price, PAGE_TWO[index].price, { at: '<', duration: 0.3, chars: '0123456789' }),
  )
  tl.to(q('pager-1'), { backgroundColor: 'rgba(0,0,0,0)', color: '#555555', duration: 0.2 }, '<')
  tl.to(q('pager-2'), { backgroundColor: '#111111', color: '#ffffff', duration: 0.2 }, '<')
  count('page-count', 2, { from: 1, at: '<', duration: 0.2 })
  phase('extracting')
  tl.to(q('tbody'), {
    y: -Math.max(0, ROWS.length * ROW_H - pos('rows-box').h),
    duration: 0.6,
    ease: 'power2.inOut',
  })
  tl.fromTo(
    qa('row').slice(PAGE_ONE.length),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.25, stagger: 0.06, ease: 'power3.out' },
    '<',
  )
  count('row-count', ROWS.length, { from: PAGE_ONE.length, at: '<', duration: 0.5 })
  phase('done', '>')

  step(3, '+=0.4')
  move('export-XLSX')
  click('export-XLSX')
  tl.fromTo(
    q('file'),
    { opacity: 0, y: 8 },
    { opacity: 1, y: 0, duration: 0.3, ease: 'back.out(2)' },
    '<',
  )
  cursorOut('+=0.4')
  final()
  wait(1.4)
}

function Field({ label, d, placeholder }: { label: string; d: string; placeholder?: string }) {
  return (
    <div>
      <p className="mb-0.5 text-[9px] font-medium text-ink-soft">{label}</p>
      <div className="flex h-6 items-center rounded-md border border-line bg-canvas/80 px-1.5 font-mono text-[9px] text-ink">
        <span data-d={d} className="truncate" />
        {placeholder ? <span className="text-muted">{placeholder}</span> : null}
      </div>
    </div>
  )
}

export default function Demo() {
  return (
    <DemoStage
      label="Data Scraper detecting a product grid, crawling two pages and exporting a spreadsheet"
      steps={CAPTIONS}
      build={build}
    >
      <BrowserChrome
        url={`https://${HOST}/new`}
        panelWidth={252}
        panel={
          <div className="flex h-full flex-col">
            <DockHeader />
            <div className="relative flex min-h-0 flex-1 flex-col gap-1.5 p-2.5">
              <div className="flex gap-1">
                <span
                  data-d="detect"
                  className="flex h-6 items-center gap-1 rounded-md bg-[var(--accent)] px-2 text-[9.5px] font-medium text-canvas"
                >
                  <ZapIcon className="size-3" /> Auto-detect grid
                </span>
                <span className="flex h-6 items-center gap-1 rounded-md border border-line-strong px-2 text-[9.5px] text-ink-soft">
                  <TargetIcon className="size-3" /> Pick rows
                </span>
              </div>
              <Field label="Row selector" d="row-sel" />
              <div className="grid grid-cols-2 gap-1.5">
                <div>
                  <p className="mb-0.5 text-[9px] font-medium text-ink-soft">Pagination</p>
                  <span
                    data-d="mode"
                    className="flex h-6 items-center justify-between rounded-md border border-line bg-canvas/80 px-1.5 text-[9px] text-ink"
                  >
                    <span data-d="mode-text">Single page</span>{' '}
                    <span className="text-muted">▾</span>
                  </span>
                </div>
                <Field label="Next page selector" d="next-sel" />
              </div>
              <div className="flex items-center gap-1.5">
                <span
                  data-d="crawl"
                  className="flex h-6 items-center rounded-md bg-ink/10 px-2 text-[9.5px] text-ink"
                >
                  Start crawl
                </span>
                <p className="text-[9px] text-muted">
                  <span data-d="row-count" className="font-medium text-ink">
                    0
                  </span>{' '}
                  rows · <span data-d="page-count">1</span> pages · Phase:{' '}
                  <strong data-d="phase" className="text-ink-soft">
                    idle
                  </strong>
                </p>
              </div>
              <div className="flex gap-1">
                {EXPORTS.map((name) => (
                  <span
                    key={name}
                    data-d={`export-${name}`}
                    className="rounded-md border border-line-strong px-1.5 py-0.5 text-[9px] text-ink-soft"
                  >
                    {name}
                  </span>
                ))}
              </div>
              <div className="relative min-h-0 flex-1 overflow-hidden rounded-md border border-line bg-canvas/60 text-[9px]">
                <div className="flex border-b border-line px-2 py-0.5 text-muted">
                  <span className="w-6">#</span>
                  <span className="flex-1">name</span>
                  <span>price</span>
                </div>
                <div
                  data-d="rows-box"
                  className="absolute inset-x-0 bottom-0 top-[17px] overflow-hidden"
                >
                  <div data-d="tbody">
                    {ROWS.map((row, index) => (
                      <div
                        key={row.name}
                        data-d="row"
                        className="flex items-center px-2 opacity-0"
                        style={{ height: ROW_H }}
                      >
                        <span className="w-6 font-mono text-muted">{index + 1}</span>
                        <span className="flex-1 truncate text-ink">{row.name}</span>
                        <span className="font-mono text-ink-soft">{row.price}</span>
                      </div>
                    ))}
                  </div>
                </div>
              </div>
              <span
                data-d="file"
                className="absolute left-1/2 top-[38px] -translate-x-1/2 whitespace-nowrap rounded-full bg-[var(--accent)] px-2.5 py-1 font-mono text-[9px] font-medium text-canvas opacity-0"
              >
                {HOST}-2026-10-24.xlsx
              </span>
            </div>
          </div>
        }
      >
        <div className="h-full bg-[#fafafa] px-3 pt-3 text-[#111]">
          <h3 className="text-[13px] font-bold tracking-tight">New arrivals</h3>
          <div className="relative mt-2">
            <div className="grid grid-cols-3 gap-2">
              {PAGE_ONE.map((item, index) => (
                <div
                  key={item.name}
                  data-d="card"
                  className="rounded-lg bg-white p-1.5 shadow-sm outline outline-2 outline-offset-1 outline-transparent"
                >
                  <div className="h-10 rounded-md" style={{ background: mockImage(index) }} />
                  <p data-d="card-name" className="mt-1 truncate text-[8.5px] font-medium">
                    {item.name}
                  </p>
                  <p data-d="card-price" className="text-[8.5px] text-[#7c3aed]">
                    {item.price}
                  </p>
                </div>
              ))}
            </div>
            <span
              data-d="lasso"
              className="pointer-events-none absolute -inset-1.5 rounded-xl border-2 border-dashed border-[#60a5fa] opacity-0"
            />
          </div>
          <div className="mt-3 flex items-center justify-center gap-1 text-[9px]">
            {['1', '2'].map((page, index) => (
              <span
                key={page}
                data-d={`pager-${page}`}
                className={cn(
                  'flex size-5 items-center justify-center rounded',
                  index === 0 ? 'bg-[#111] text-white' : 'text-[#555]',
                )}
              >
                {page}
              </span>
            ))}
            <span data-d="pager-next" className="rounded px-1.5 py-0.5 text-[#555]">
              Next →
            </span>
          </div>
        </div>
      </BrowserChrome>
    </DemoStage>
  )
}
